/* * https://www.vbforums.com/showthread.php?857881-Custom-JSON-Font-Serialization        JsonSerializerSettings settings = new JsonSerializerSettings();        settings.Converters.Add(new FontConverter());        var serialized = JsonConvert.SerializeObject(this.Font, settings);        Debug.WriteLine(serialized);        Font deserialized = JsonConvert.DeserializeObject<Font>(serialized, settings);        Debug.WriteLine(deserialized); */using LessonEditor.objects;using Newtonsoft.Json;using System;using System.Drawing;namespace LessonEditor.utils {    internal class FontConverter : JsonConverter {        public override void WriteJson(JsonWriter writer, object value, JsonSerializer serializer) {            var fontProxy = JsonFont.FromFont((Font)value);            writer.WriteStartObject();            EmitProperty(writer, "Name", fontProxy.Name);            EmitProperty(writer, "Size", fontProxy.Size);            EmitProperty(writer, "Bold", fontProxy.Bold);            EmitProperty(writer, "Italic", fontProxy.Italic);            EmitProperty(writer, "Underline", fontProxy.Underline);            writer.WriteEndObject();        }        public override object ReadJson(JsonReader reader, Type objectType, object existingValue, JsonSerializer serializer) {            JsonFont fontProxy = new JsonFont();            while (reader.Read()) {                switch (reader.TokenType) {                    case object _ when JsonToken.PropertyName: {                            ReadProperty(reader, fontProxy);                            break;                        }                    case object _ when JsonToken.EndObject: {                            break;                            break;                        }                }            }            return fontProxy.ToFont();        }        public override bool CanConvert(Type objectType) {            return objectType == typeof(Font);        }        private void EmitProperty<T>(JsonWriter writer, string name, T value) {            writer.WritePropertyName(name);            writer.WriteValue(value);        }        private void ReadProperty(JsonReader reader, JsonFont proxy) {            switch (reader.Value) {                case "Name": {                        proxy.Name = reader.ReadAsString();                        break;                    }                case "Size": {                        proxy.Size = reader.ReadAsInt32();                        break;                    }                case "Bold": {                        proxy.Bold = reader.ReadAsBoolean();                        break;                    }                case "Italic": {                        proxy.Italic = reader.ReadAsBoolean();                        break;                    }                case "Underline": {                        proxy.Underline = reader.ReadAsBoolean();                        break;                    }            }        }    }}using System.Drawing;namespace LessonEditor.objects {    public class JsonFont {        public string Name { get; set; }        public int Size { get; set; }        public bool Bold { get; set; }        public bool Italic { get; set; }        public bool Underline { get; set; }        public JsonFont() {}        public static JsonFont FromFont(Font theFont) {            JsonFont result = new JsonFont {                Name = theFont.FontFamily.Name,                Size = (int)theFont.Size,                Bold = theFont.Style == FontStyle.Bold,                Italic = theFont.Style == FontStyle.Italic,                Underline = theFont.Style == FontStyle.Underline,            };            return result;        }        public Font ToFont() {            FontStyle style = FontStyle.Regular;            if (Bold) style |= FontStyle.Bold;            if (Italic) style |= FontStyle.Italic;            if (Underline) style |= FontStyle.Underline;            Font f = new Font(Name, Size, style);            return f;        }    }}